ee:message.ee:set-payload:
%dw 2.0
output application/xml encoding="UTF-8"
---
{
  Request @(Version: p('sys.request-version')): {
    ReqClientID: {
      DID: vars.merchantConfig.did,
      App: vars.merchantConfig.appId,
      Auth: vars.merchantConfig.merchantId ++ "|" ++ vars.merchantConfig.tid,
      ClientRef: ((random() * 9000000 + 1000000) as String {format: "0"}) ++ p('sys.application-version')
    },
    Transaction: {
      ServiceID: vars.merchantConfig.serviceId as Number,
      Payload @(Encoding: p('sys.payload-encoding')): vars.fdPayload
    }
  }
}

%dw 2.0
output application/json
var fdXml       = read(payload, "application/xml")
var statusCode  = fdXml.Response.Status.StatusCode as String default "UNKNOWN"
var returnCode  = fdXml.Response.TransactionResponse.ReturnCode as String default ""
var fdPayloadStr = fdXml.Response.TransactionResponse.Payload as String default ""
var fieldMap = if (fdPayloadStr != "")
    (fdPayloadStr splitBy "|1C") reduce (field, acc = {}) ->
        if (sizeOf(field) >= 3) acc ++ {(field[0 to 1]): field[2 to -1]}
        else if (sizeOf(field) == 2) acc ++ {(field[0 to 1]): ""}
        else acc
    else {}
fun getField(code: String) = fieldMap[code] default null
var avail   = (getField("76") default "0") as Number default 0
var locked  = (getField("78") default "0") as Number default 0
var balVal  = (avail - locked) * 0.01
var currRaw = getField("C0") default "840"
var curr    = if (currRaw == "124") "CAD" else "USD"
var succeeded = statusCode == "OK" and returnCode == "00"
---
{
  (request_id: vars.requestId) if (vars.requestId != null),
  transaction_result: {
    is_succeeded: succeeded,
    (card_number:     getField("70"))       if (getField("70") != null),
    (balance: {
      value:         balVal,
      currency_code: curr
    })                                       if succeeded,
    (expiration_date: getField("A0"))       if (getField("A0") != null),
    (card_class:      getField("B0"))       if (getField("B0") != null),
    (promotion_code:  getField("F2"))       if (getField("F2") != null),
    (error_description: (
      {
        "01": "Insufficient funds.",
        "04": "Inactive account.",
        "05": "Expired card.",
        "08": "Already active.",
        "32": "Account locked.",
        "35": "Generic denial."
      }[getField("39") default ""] default ("FD response code: " ++ (getField("39") default "unknown"))
    ))                                       if (!succeeded)
  }
}
